  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello मंटू जी आपको Legrand double pole MCB की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "जी।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "कितने piece चाहिए होंगे आपको?"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "फिलहाल तो अभी testing के लिए एक piece चाहिए।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "चलिए अब rated current के बारे में बात कर लेते हैं।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "आपको कौन सा चाहिए?"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "16 ampere, 10 ampere या कुछ और?"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "one six MP चाहिए या ten MP दोनों में कोई भी ले लेंगे।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "ठीक है मैं 16 ampere note कर लेती हूं।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "अब बताइए number of poles में क्या prefer करेंगे one pole, two pole या कोई और?"
    },
    {
      "i": 14,
      "speaker": "caller",
      "text": "दो चार।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "क्षमा कीजिए मैं समझ नहीं पाई।"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "आप number of poles के लिए one pole, two pole या कोई और option prefer करेंगे?"
    },
    {
      "i": 17,
      "speaker": "caller",
      "text": "Two pole two pole."
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "ठीक है मैं ये details seller पे छोड़ देती हूं।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 20,
      "speaker": "caller",
      "text": "ठीक।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 22,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    },
    {
      "i": 23,
      "speaker": "caller",
      "text": "ठीक।"
    },
    {
      "i": 24,
      "speaker": "caller",
      "text": "पूरा"
    }
  ]
}
